<?php
$root=dirname(__DIR__);require_once $root.'/app/bootstrap.php';require_once $root.'/app/MigrationService.php';MigrationService::run();require_once $root.'/app/AuthService.php';require_once $root.'/app/BehaviorService.php';require_once $root.'/app/CausalService.php';require_once $root.'/app/DynamicOpportunityService.php';require_once $root.'/app/CharacterAutomationService.php';require_once $root.'/app/StateSyncService.php';require_once $root.'/app/SimulationService.php';require_once $root.'/app/LobbyService.php';AuthService::boot();
$error=null;$notice=null;$view=(string)($_GET['view']??'home');
if($_SERVER['REQUEST_METHOD']==='POST'){try{AuthService::requireCsrf();$action=(string)($_POST['action']??'');
 if($action==='login'){AuthService::verifyLoginCaptcha($_POST);AuthService::login((string)$_POST['email'],(string)$_POST['password']);header('Location: ./');exit;}
 if($action==='register'){$registered=AuthService::register((string)$_POST['email'],(string)$_POST['display_name'],(string)$_POST['password'],(string)($_POST['invite']??''),(string)($_POST['game_invite']??''));$invitedGame=(int)($registered['_game_id']??0);header('Location: '.($invitedGame?'lobby.php?game='.$invitedGame:'./'));exit;}
 if($action==='logout'){AuthService::logout();header('Location: ./');exit;}
 if($action==='forgot'){AuthService::createPasswordResetForEmail((string)$_POST['email']);$notice='If that account exists, a password-reset email has been sent.';$view='forgot';}
 if($action==='reset'){AuthService::resetPassword((string)$_POST['token'],(string)$_POST['password']);$notice='Password updated. You can now sign in.';$view='login';}
 if($action==='create_game'){$u=AuthService::requireLogin();$state=LobbyService::createGame((int)$u['user_id'],(string)$_POST['plot_code'],(int)($_POST['duration_seconds']??300));header('Location: lobby.php?game='.(int)$state['game']['game_id']);exit;}
 if($action==='join_game'){$u=AuthService::requireLogin();$state=LobbyService::joinByCode((int)$u['user_id'],(string)$_POST['join_code']);header('Location: lobby.php?game='.(int)$state['game']['game_id']);exit;}
 if($action==='request_writer'){$u=AuthService::requireLogin();AuthService::requestWriterAccess((int)$u['user_id'],(string)($_POST['request_text']??''));$notice='Your Story Writer request has been sent for administrator review.';}
}catch(Throwable$e){$error=$e->getMessage();}}
$user=AuthService::currentUser();$captchaMode=AuthService::captchaMode();$captchaSiteKey=$captchaMode==='GOOGLE'?AuthService::setting('GOOGLE_RECAPTCHA_SITE_KEY'):'';$plots=[];$games=[];$durationOptions=[];if($user){$q=db()->query('SELECT code,title,genre,setting_name,max_players FROM plots WHERE status="active" ORDER BY title');$plots=$q->fetchAll();$durationOptions=db()->query('SELECT duration_seconds,label_text FROM platform_game_durations WHERE active=1 ORDER BY sort_order,duration_seconds')->fetchAll();$games=LobbyService::userGames((int)$user['user_id']);}
function csrf_field(): string{return'<input type="hidden" name="csrf_token" value="'.e(AuthService::csrfToken()).'">';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Toinky</title><style>
